import numpy as np

def mse(y_true, y_pred):
    # mean of the squared errors
    return np.mean((y_true - y_pred)**2)

def rmse(y_true, y_pred):
    # square root of the mse — same unit as the target
    return np.sqrt(mse(y_true, y_pred))

def mae(y_true, y_pred):
    # mean of the absolute errors
    return np.mean(np.abs(y_true - y_pred))

# check with the values from the assignment
y_true = np.array([3.0, -0.5, 2.0, 7.0])
y_pred = np.array([2.5,  0.0, 2.0, 8.0])

print('mse :', mse(y_true, y_pred))   # expected 0.375
print('rmse:', rmse(y_true, y_pred))  # expected 0.6123724356957945
print('mae :', mae(y_true, y_pred))   # expected 0.5
